def find_minimal_number(d, s):
    if s > d * 9:
        return -1

    # Start with the smallest number that is divisible by d
    n = (10 ** (d - 1)) % d
    if n == 0:
        n = d

    # Find the smallest number with sum of digits s
    while True:
        if sum(int(digit) for digit in str(n)) == s:
            return n
        n += d
        if n > 10 ** (d - 1) * 9:
            return -1

